//! Capture library: a JSON index of captures with metadata, tags, search, filter and sort.
//! The index is written atomically; thumbnails are generated by the engine, not stored here.
#![deny(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::unimplemented,
    clippy::todo,
    clippy::unreachable
)]

use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};

#[derive(Debug, thiserror::Error)]
pub enum LibraryError {
    #[error("io: {0}")]
    Io(String),
    #[error("index is corrupt: {0}")]
    Corrupt(String),
    #[error("no entry with id {0}")]
    NoEntry(u64),
    #[error("invalid tag `{0}`")]
    BadTag(String),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Kind {
    Image,
    Video,
    Gif,
    Text,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Entry {
    pub id: u64,
    pub kind: Kind,
    pub path: PathBuf,
    pub title: String,
    pub app: String,
    pub url: Option<String>,
    /// Unix seconds.
    pub created: i64,
    pub width: u32,
    pub height: u32,
    pub tags: Vec<String>,
    /// Full text for a [`Kind::Text`] entry. Empty for images and video. Capped by the writer.
    #[serde(default)]
    pub body: String,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum SortBy {
    #[default]
    DateDesc,
    DateAsc,
    Title,
    App,
}

#[derive(Clone, Debug, Default)]
pub struct Query {
    pub text: Option<String>,
    pub kind: Option<Kind>,
    pub app: Option<String>,
    pub tag: Option<String>,
    pub from: Option<i64>,
    pub to: Option<i64>,
    pub sort: SortBy,
}

#[derive(Debug, Default, Serialize, Deserialize)]
pub struct Library {
    entries: Vec<Entry>,
    next_id: u64,
    #[serde(skip)]
    index_path: Option<PathBuf>,
}

fn norm_tag(t: &str) -> Result<String, LibraryError> {
    let t = t.trim().to_lowercase();
    if t.is_empty() || t.chars().count() > 64 || t.chars().any(char::is_control) {
        return Err(LibraryError::BadTag(t));
    }
    Ok(t)
}

impl Library {
    pub fn in_memory() -> Self {
        Self {
            next_id: 1,
            ..Default::default()
        }
    }

    /// Open (or create) the library whose index lives at `<dir>/library.json`.
    pub fn open(dir: &Path) -> Result<Self, LibraryError> {
        std::fs::create_dir_all(dir).map_err(|e| LibraryError::Io(e.to_string()))?;
        let path = dir.join("library.json");
        let mut lib = if path.exists() {
            let text =
                std::fs::read_to_string(&path).map_err(|e| LibraryError::Io(e.to_string()))?;
            serde_json::from_str::<Library>(&text)
                .map_err(|e| LibraryError::Corrupt(e.to_string()))?
        } else {
            Library::in_memory()
        };
        lib.next_id = lib
            .next_id
            .max(lib.entries.iter().map(|e| e.id + 1).max().unwrap_or(1))
            .max(1);
        lib.index_path = Some(path);
        Ok(lib)
    }

    pub fn save(&self) -> Result<(), LibraryError> {
        let Some(path) = &self.index_path else {
            return Ok(());
        };
        let json =
            serde_json::to_vec_pretty(self).map_err(|e| LibraryError::Corrupt(e.to_string()))?;
        let tmp = path.with_extension("json.tmp");
        std::fs::write(&tmp, json).map_err(|e| LibraryError::Io(e.to_string()))?;
        std::fs::rename(&tmp, path).map_err(|e| LibraryError::Io(e.to_string()))
    }

    pub fn add(&mut self, mut e: Entry) -> Result<u64, LibraryError> {
        e.id = self.next_id.max(1);
        self.next_id = e.id + 1;
        e.tags = e
            .tags
            .iter()
            .map(|t| norm_tag(t))
            .collect::<Result<_, _>>()?;
        let id = e.id;
        self.entries.push(e);
        self.save()?;
        Ok(id)
    }

    /// Rewrite entry paths (files moved on disk); `map` returns the new path or `None` to keep it.
    /// Saves once when anything changed and returns how many entries moved.
    pub fn relocate(
        &mut self,
        map: impl Fn(&Path) -> Option<PathBuf>,
    ) -> Result<usize, LibraryError> {
        let mut n = 0;
        for e in &mut self.entries {
            if let Some(p) = map(&e.path) {
                e.path = p;
                n += 1;
            }
        }
        if n > 0 {
            self.save()?;
        }
        Ok(n)
    }

    pub fn get(&self, id: u64) -> Option<&Entry> {
        self.entries.iter().find(|e| e.id == id)
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }
    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    pub fn remove(&mut self, id: u64) -> Result<Entry, LibraryError> {
        let i = self
            .entries
            .iter()
            .position(|e| e.id == id)
            .ok_or(LibraryError::NoEntry(id))?;
        let e = self.entries.remove(i);
        self.save()?;
        Ok(e)
    }

    pub fn add_tag(&mut self, id: u64, tag: &str) -> Result<(), LibraryError> {
        let tag = norm_tag(tag)?;
        let e = self
            .entries
            .iter_mut()
            .find(|e| e.id == id)
            .ok_or(LibraryError::NoEntry(id))?;
        if !e.tags.contains(&tag) {
            e.tags.push(tag);
        }
        self.save()
    }

    pub fn remove_tag(&mut self, id: u64, tag: &str) -> Result<(), LibraryError> {
        let tag = norm_tag(tag)?;
        let e = self
            .entries
            .iter_mut()
            .find(|e| e.id == id)
            .ok_or(LibraryError::NoEntry(id))?;
        e.tags.retain(|t| *t != tag);
        self.save()
    }

    /// All distinct tags with their counts, most used first.
    pub fn tags(&self) -> Vec<(String, usize)> {
        let mut m: std::collections::BTreeMap<&str, usize> = std::collections::BTreeMap::new();
        for e in &self.entries {
            for t in &e.tags {
                *m.entry(t).or_default() += 1;
            }
        }
        let mut v: Vec<(String, usize)> = m.into_iter().map(|(k, n)| (k.to_string(), n)).collect();
        v.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
        v
    }

    pub fn query(&self, q: &Query) -> Vec<&Entry> {
        let text = q.text.as_ref().map(|t| t.to_lowercase());
        let tag = q.tag.as_ref().map(|t| t.trim().to_lowercase());
        let mut v: Vec<&Entry> = self
            .entries
            .iter()
            .filter(|e| q.kind.is_none_or(|k| e.kind == k))
            .filter(|e| q.app.as_ref().is_none_or(|a| e.app.eq_ignore_ascii_case(a)))
            .filter(|e| tag.as_ref().is_none_or(|t| e.tags.contains(t)))
            .filter(|e| {
                q.from.is_none_or(|f| e.created >= f) && q.to.is_none_or(|t| e.created <= t)
            })
            .filter(|e| {
                text.as_ref().is_none_or(|t| {
                    e.title.to_lowercase().contains(t)
                        || e.body.to_lowercase().contains(t)
                        || e.app.to_lowercase().contains(t)
                        || e.url.as_ref().is_some_and(|u| u.to_lowercase().contains(t))
                        || e.tags.iter().any(|g| g.contains(t))
                        || e.path.to_string_lossy().to_lowercase().contains(t)
                })
            })
            .collect();
        match q.sort {
            SortBy::DateDesc => v.sort_by(|a, b| b.created.cmp(&a.created).then(b.id.cmp(&a.id))),
            SortBy::DateAsc => v.sort_by(|a, b| a.created.cmp(&b.created).then(a.id.cmp(&b.id))),
            SortBy::Title => v.sort_by_key(|e| e.title.to_lowercase()),
            SortBy::App => v.sort_by_key(|e| e.app.to_lowercase()),
        }
        v
    }

    /// Most recent captures (the tray).
    pub fn recent(&self, n: usize) -> Vec<&Entry> {
        self.query(&Query::default()).into_iter().take(n).collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn entry(title: &str, app: &str, created: i64, kind: Kind) -> Entry {
        Entry {
            id: 0,
            kind,
            path: PathBuf::from(format!("C:\\caps\\{title}.scit")),
            title: title.into(),
            app: app.into(),
            url: None,
            created,
            width: 10,
            height: 10,
            tags: vec![],
            body: String::new(),
        }
    }

    fn lib() -> Library {
        let mut l = Library::in_memory();
        l.add(entry("Invoice", "chrome.exe", 100, Kind::Image))
            .unwrap();
        l.add(entry("Demo", "code.exe", 300, Kind::Video)).unwrap();
        l.add(entry("Bug", "chrome.exe", 200, Kind::Image)).unwrap();
        l
    }

    #[test]
    fn filter_sort_search() {
        let l = lib();
        let q = |f: &dyn Fn(&mut Query)| {
            let mut q = Query::default();
            f(&mut q);
            l.query(&q)
                .iter()
                .map(|e| e.title.clone())
                .collect::<Vec<_>>()
        };
        assert_eq!(q(&|_| {}), ["Demo", "Bug", "Invoice"]);
        assert_eq!(q(&|q| q.sort = SortBy::DateAsc), ["Invoice", "Bug", "Demo"]);
        assert_eq!(
            q(&|q| q.app = Some("CHROME.EXE".into())),
            ["Bug", "Invoice"]
        );
        assert_eq!(q(&|q| q.kind = Some(Kind::Video)), ["Demo"]);
        assert_eq!(q(&|q| q.text = Some("inv".into())), ["Invoice"]);
        let mut text = entry("Grab", "", 400, Kind::Text);
        text.body = "invoice total 42".into();
        let mut with_body = lib();
        with_body.add(text).unwrap();
        assert_eq!(
            with_body
                .query(&Query {
                    text: Some("total".into()),
                    ..Default::default()
                })
                .len(),
            1
        );
        assert_eq!(
            q(&|q| {
                q.from = Some(150);
                q.to = Some(250);
            }),
            ["Bug"]
        );
        assert_eq!(q(&|q| q.sort = SortBy::Title), ["Bug", "Demo", "Invoice"]);
        assert_eq!(l.recent(2).len(), 2);
    }

    #[test]
    fn tags_normalize_and_count() {
        let mut l = lib();
        l.add_tag(1, " Billing ").unwrap();
        l.add_tag(1, "billing").unwrap();
        l.add_tag(3, "billing").unwrap();
        l.add_tag(3, "urgent").unwrap();
        assert_eq!(
            l.get(1).map(|e| e.tags.clone()),
            Some(vec!["billing".to_string()])
        );
        assert_eq!(l.tags()[0], ("billing".to_string(), 2));
        assert!(l.add_tag(1, "  ").is_err());
        assert!(l.add_tag(1, "a\u{7}b").is_err());
        assert!(l.add_tag(99, "x").is_err());
        l.remove_tag(3, "BILLING").unwrap();
        let hits = l.query(&Query {
            tag: Some("urgent".into()),
            ..Default::default()
        });
        assert_eq!(hits.len(), 1);
    }

    #[test]
    fn persists_and_detects_corruption() {
        let dir = std::env::temp_dir().join(format!("scit-lib-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        {
            let mut l = Library::open(&dir).unwrap();
            l.add(entry("A", "x", 1, Kind::Gif)).unwrap();
            l.add(entry("B", "x", 2, Kind::Image)).unwrap();
        }
        let mut l = Library::open(&dir).unwrap();
        assert_eq!(l.len(), 2);
        assert_eq!(l.add(entry("C", "x", 3, Kind::Image)).unwrap(), 3);
        l.remove(1).unwrap();
        assert!(l.remove(1).is_err());
        std::fs::write(dir.join("library.json"), "{ nope").unwrap();
        assert!(matches!(Library::open(&dir), Err(LibraryError::Corrupt(_))));
        std::fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn relocate_rewrites_matching_paths_only() {
        let mut l = lib();
        let n = l
            .relocate(|p| {
                p.strip_prefix("C:\\caps")
                    .ok()
                    .filter(|r| r.to_string_lossy().starts_with('B'))
                    .map(|r| Path::new("D:\\new").join(r))
            })
            .unwrap();
        assert_eq!(n, 1);
        assert_eq!(l.get(3).unwrap().path, Path::new("D:\\new\\Bug.scit"));
        assert_eq!(l.get(1).unwrap().path, Path::new("C:\\caps\\Invoice.scit"));
        assert_eq!(l.relocate(|_| None).unwrap(), 0);
    }
}
